(function(){
  function LiteTerminal(opts){
    this.opts=opts||{};this.cols=120;this.rows=32;this._handlers=[];this._buf='';
  }
  LiteTerminal.prototype.open=function(el){
    this.el=el;this.wrap=document.createElement('div');this.wrap.className='xterm-lite';
    this.out=document.createElement('pre');this.out.className='xterm-lite-output';
    this.input=document.createElement('textarea');this.input.className='xterm-lite-input';this.input.spellcheck=false;this.input.autocomplete='off';this.input.autocapitalize='off';
    this.wrap.appendChild(this.out);this.wrap.appendChild(this.input);el.appendChild(this.wrap);
    var self=this;this.input.addEventListener('keydown',function(e){
      var data='';
      if(e.key==='Enter')data='\r';else if(e.key==='Backspace')data='\x7f';else if(e.key==='Tab')data='\t';else if(e.key==='ArrowUp')data='\x1b[A';else if(e.key==='ArrowDown')data='\x1b[B';else if(e.key==='ArrowRight')data='\x1b[C';else if(e.key==='ArrowLeft')data='\x1b[D';else if(e.ctrlKey&&e.key&&e.key.length===1)data=String.fromCharCode(e.key.toUpperCase().charCodeAt(0)-64);else if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&e.key&&e.key.length===1)data=e.key;
      if(data){e.preventDefault();self._handlers.forEach(function(h){h(data);});}
    });
  };
  LiteTerminal.prototype.focus=function(){if(this.input)this.input.focus();};
  LiteTerminal.prototype.write=function(data){
    var text=data instanceof Uint8Array?new TextDecoder().decode(data):String(data);
    text=text.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g,'');
    this._buf=(this._buf+text).slice(-120000);if(this.out){this.out.textContent=this._buf;this.out.scrollTop=this.out.scrollHeight;}
  };
  LiteTerminal.prototype.onData=function(handler){this._handlers.push(handler);return{dispose:function(){}};};
  window.Terminal=window.Terminal||LiteTerminal;
})();
